inline int graphicsTest(const fs::path& folder){try{Renderer r;UINT index=0;BOOL found=FALSE;check(r.fonts?r.fonts->FindFamilyName(L"Noto Sans KR",&index,&found):E_FAIL,"번들 한글 폰트 컬렉션 실패");if(!found)throw std::runtime_error("Noto Sans KR 로딩 실패");Com<ID3D11Device> device;Com<ID3D11DeviceContext> context;D3D_FEATURE_LEVEL level;check(D3D11CreateDevice(nullptr,D3D_DRIVER_TYPE_HARDWARE,nullptr,D3D11_CREATE_DEVICE_BGRA_SUPPORT,nullptr,0,D3D11_SDK_VERSION,&device,&level,&context),"GPU Direct3D 장치 생성 실패");D3D11_TEXTURE2D_DESC desc{};desc.Width=256;desc.Height=128;desc.MipLevels=desc.ArraySize=1;desc.Format=DXGI_FORMAT_B8G8R8A8_UNORM;desc.SampleDesc.Count=1;desc.BindFlags=D3D11_BIND_RENDER_TARGET|D3D11_BIND_SHADER_RESOURCE;Com<ID3D11Texture2D> texture;check(device->CreateTexture2D(&desc,nullptr,&texture),"GPU 텍스처 생성 실패");Com<IDXGISurface> surface;check(texture.As(&surface),"GPU Surface 변환 실패");Com<ID2D1RenderTarget> target;check(r.factory->CreateDxgiSurfaceRenderTarget(surface.Get(),D2D1::RenderTargetProperties(D2D1_RENDER_TARGET_TYPE_HARDWARE,D2D1::PixelFormat(DXGI_FORMAT_B8G8R8A8_UNORM,D2D1_ALPHA_MODE_PREMULTIPLIED)),&target),"GPU Direct2D 렌더 대상 실패");target->BeginDraw();target->Clear(color(0x111111));Com<ID2D1SolidColorBrush> brush;target->CreateSolidColorBrush(color(0x336699),&brush);target->FillRectangle(D2D1::RectF(0,0,128,128),brush.Get());Com<IDWriteTextFormat> font;r.write->CreateTextFormat(L"Noto Sans KR",r.fonts.Get(),DWRITE_FONT_WEIGHT_NORMAL,DWRITE_FONT_STYLE_NORMAL,DWRITE_FONT_STRETCH_NORMAL,18,L"ko-KR",&font);target->DrawTextW(L"한글 ABC",6,font.Get(),D2D1::RectF(130,10,250,90),brush.Get());check(target->EndDraw(),"GPU 그리기 실패");desc.Usage=D3D11_USAGE_STAGING;desc.CPUAccessFlags=D3D11_CPU_ACCESS_READ;desc.BindFlags=0;Com<ID3D11Texture2D> readback;device->CreateTexture2D(&desc,nullptr,&readback);context->CopyResource(readback.Get(),texture.Get());D3D11_MAPPED_SUBRESOURCE mapped;check(context->Map(readback.Get(),0,D3D11_MAP_READ,0,&mapped),"GPU 결과 읽기 실패");auto pixel=(const BYTE*)mapped.pData;/* The black theme maps RGB 0x336699 to monochrome 0x5e5e5e. */if(pixel[0]!=0x5e||pixel[1]!=0x5e||pixel[2]!=0x5e){context->Unmap(readback.Get(),0);throw std::runtime_error("GPU 픽셀 검증 실패");}context->Unmap(readback.Get(),0);atomicWrite(folder/"native-graphics-result.json",json{{"ok",true},{"hardware_gpu",true},{"direct2d",true},{"bundled_korean_font",true},{"gui_opened",false}}.dump(2));return 0;}catch(const std::exception& e){atomicWrite(folder/"native-graphics-result.json",json{{"ok",false},{"error",e.what()},{"gui_opened",false}}.dump(2));return 1;}}
inline int migrationTest(const fs::path& folder){try{auto before=readJson(folder/"config/channels.json");Store s(folder);s.load();s.save();auto after=readJson(folder/"config/channels.json");if(before["channels"].size()!=after["channels"].size()||before["active"]!=after["active"])throw std::runtime_error("프로젝트 목록 변경");for(size_t i=0;i<before["channels"].size();i++){auto& a=before["channels"][i];auto& b=after["channels"][i];if(a["id"]!=b["id"]||a["name"]!=b["name"])throw std::runtime_error("프로젝트 식별자 변경");for(auto key:{"drafts","negative"})if(a["state"].contains(key)&&a["state"][key]!=b["state"][key])throw std::runtime_error("프롬프트 변경");if(a["state"]["project"].contains("references")&&a["state"]["project"]["references"]!=b["state"]["project"]["references"])throw std::runtime_error("참조 변경");}atomicWrite(folder/"native-migration-result.json",json{{"ok",true},{"projects",before["channels"].size()},{"gui_opened",false}}.dump(2));return 0;}catch(const std::exception& e){atomicWrite(folder/"native-migration-result.json",json{{"ok",false},{"error",e.what()}}.dump(2));return 1;}}
inline int imageWorkerTest(const fs::path& folder){try{ImageWorker worker;size_t submitted=0,finished=0;auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(12);while(finished<100&&std::chrono::steady_clock::now()<deadline){while(submitted<100&&worker.add(folder/L"valid.png",1)){submitted++;}for(auto& result:worker.take()){if(result.failed||result.width!=32||result.height!=48||result.pixels.size()!=32*48*4)throw std::runtime_error("Image decode lost pixels");finished++;}Sleep(5);}if(finished!=100)throw std::runtime_error("Image queue dropped accepted requests");worker.add(folder/L"invalid.png",2,true);bool failed=false;for(int i=0;i<200&&!failed;i++){for(auto& result:worker.take())failed=result.failed&&result.preview;Sleep(5);}if(!failed)throw std::runtime_error("Invalid image silently left loading");worker.add(folder/L"valid.png",3,true);bool recovered=false;for(int i=0;i<200&&!recovered;i++){for(auto& result:worker.take())recovered=!result.failed&&result.preview;Sleep(5);}if(!recovered)throw std::runtime_error("Preview did not recover");atomicWrite(folder/"native-image-result.json",json{{"ok",true},{"images",finished},{"failure_reported",failed},{"preview_recovered",recovered},{"gui_opened",false}}.dump(2));return 0;}catch(const std::exception& e){atomicWrite(folder/"native-image-result.json",json{{"ok",false},{"error",e.what()},{"gui_opened",false}}.dump(2));return 1;}}

inline int sidebarTest(const fs::path& folder){try{
 Store store(folder);store.load();auto first=store.active;store.current()["name"]="첫 작업";store.state["drafts"]["prompt"]="원본, (태그:1.2)";store.save();store.create("두 번째");auto second=store.active;store.create("세 번째");auto third=store.active;auto originalState=store.state;auto originalSettings=store.settings;
 auto a=addProjectFolder(store.doc,"캐릭터"),b=addProjectFolder(store.doc,"장면");moveProject(store.doc,second,a);moveProject(store.doc,third,a,second);auto rows=projectSidebarRows(store.doc,L"");if(rows.size()!=5||rows[1].key!=third||rows[2].key!=second)throw std::runtime_error("Folder project order mismatch");
 moveProject(store.doc,first,a,third);auto filtered=projectSidebarRows(store.doc,L"두 번째");if(filtered.size()!=2||filtered[1].key!=second)throw std::runtime_error("Folder search mismatch");store.doc["folders"][0]["collapsed"]=true;if(projectSidebarRows(store.doc,L"").size()!=2)throw std::runtime_error("Folder collapse mismatch");
 moveProjectFolder(store.doc,b,a);if(str(store.doc["folders"][0],"id")!=b)throw std::runtime_error("Folder reorder mismatch");store.save();Store loaded(folder);loaded.load();if(loaded.doc!=store.doc||loaded.active!=third||loaded.settings!=originalSettings||loaded.state!=originalState)throw std::runtime_error("Organizer restart changed project data");
 moveProject(loaded.doc,second,"","");removeProjectFolder(loaded.doc,a);if(loaded.doc["channels"].size()!=3||loaded.doc["folders"].size()!=1)throw std::runtime_error("Folder removal removed projects");for(auto& row:loaded.doc["channels"])if(projectFolder(loaded.doc,row)!="")throw std::runtime_error("Folder removal did not ungroup projects");
 auto before=loaded.doc;bool rejected=false;try{moveProject(loaded.doc,first,"missing-folder");}catch(...){rejected=true;}if(!rejected||loaded.doc!=before)throw std::runtime_error("Invalid move mutated projects");moveProject(loaded.doc,first,"",second);rows=projectSidebarRows(loaded.doc,L"");if(rows.size()!=4||rows[1].key!=third||rows[2].key!=first||rows[3].key!=second)throw std::runtime_error("Root reorder mismatch");loaded.save();
 atomicWrite(folder/"native-sidebar-result.json",json{{"ok",true},{"folder_restart",true},{"project_state_preserved",true},{"gui_opened",false}}.dump(2));return 0;
 }catch(const std::exception& e){atomicWrite(folder/"native-sidebar-result.json",json{{"ok",false},{"error",e.what()},{"gui_opened",false}}.dump(2));return 1;}}
inline int cacheTest(const fs::path& folder){try{
 ThumbnailCache<int> cache(thumbnailCapacity);for(int i=0;i<int(thumbnailCapacity);i++)cache.insert(L"z-"+std::to_wstring(i),i);
 // Reproduce loading an older page after a full cache: every incoming name sorts first.
 for(int page=9;page>=0;page--){std::vector<fs::path> visible;for(int i=0;i<12;i++){fs::path key=L"a-"+std::to_wstring(page)+L"-"+std::to_wstring(i);visible.push_back(key);cache.insert(key,i);}for(int frame=0;frame<4;frame++)for(auto& key:visible)if(!cache.find(key))throw std::runtime_error("Visible thumbnail evicted by filename order");if(cache.size()!=thumbnailCapacity)throw std::runtime_error("Thumbnail memory bound changed");}
 cache.clear();if(cache.size()!=0)throw std::runtime_error("Cache reset mismatch");atomicWrite(folder/"native-cache-result.json",json{{"ok",true},{"pages",10},{"capacity",thumbnailCapacity},{"gui_opened",false}}.dump(2));return 0;
 }catch(const std::exception& e){atomicWrite(folder/"native-cache-result.json",json{{"ok",false},{"error",e.what()},{"gui_opened",false}}.dump(2));return 1;}}

inline int layoutStyleTest(const fs::path& folder){try{
 int previous=0;for(float width:{244.f,374.f,614.f,864.f,1220.f}){GalleryLayout grid(width);if(grid.columns<previous)throw std::runtime_error("Gallery columns did not grow");previous=grid.columns;Rect area{10,20,width,400};for(int i=0;i<100;i++){auto rect=grid.tile(area,i,grid.tileHeight*2);float x=rect.x+rect.w/2,y=rect.y+rect.h/2;if(area.hit(x,y)&&grid.indexAt(area,x,y,grid.tileHeight*2,100)!=i)throw std::runtime_error("Responsive thumbnail hit test mismatch");}if(grid.columns>1&&grid.indexAt(area,area.x+grid.tileWidth+2,area.y+20,0,100)!=-1)throw std::runtime_error("Gallery gap selected an image");}
 BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=320;info.bmiHeader.biHeight=-40;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* pixels=nullptr;auto bitmap=CreateDIBSection(nullptr,&info,DIB_RGB_COLORS,&pixels,nullptr,0);auto dc=CreateCompatibleDC(nullptr);if(!bitmap||!dc)throw std::runtime_error("Offscreen option canvas failed");auto old=SelectObject(dc,bitmap);auto font=CreateFontW(-13,0,0,0,FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,DEFAULT_PITCH,L"Segoe UI");RECT rect{0,0,320,40};drawDarkChoice(dc,rect,L"SDXL",font,false,false,false);bool dark=GetPixel(dc,5,20)==RGB(46,46,50);for(int x=282;x<318;x++)for(int y=4;y<36;y++){auto pixel=GetPixel(dc,x,y);if(GetRValue(pixel)>230&&GetGValue(pixel)>230&&GetBValue(pixel)>230)dark=false;}drawDarkChoice(dc,rect,L"SDXL",font,true,true,false);bool hover=GetPixel(dc,5,20)==RGB(58,58,64);SelectObject(dc,old);DeleteObject(font);DeleteObject(bitmap);DeleteDC(dc);if(!dark||!hover)throw std::runtime_error("Dark options colors mismatch");// Exercise real native messages without showing any window or touching clipboard.
 INITCOMMONCONTROLSEX controls{sizeof controls,ICC_STANDARD_CLASSES};InitCommonControlsEx(&controls);
 auto edit=CreateWindowExW(0,L"EDIT",L"caption example",ES_AUTOHSCROLL,0,0,200,26,nullptr,nullptr,GetModuleHandle(nullptr),nullptr);if(!edit)throw std::runtime_error("Hidden edit creation failed");SetWindowSubclass(edit,textShortcutProc,8,0);BYTE keys[256],ctrl[256];GetKeyboardState(keys);memcpy(ctrl,keys,sizeof keys);ctrl[VK_CONTROL]=0x80;SetKeyboardState(ctrl);SendMessageW(edit,WM_KEYDOWN,'A',0);SetKeyboardState(keys);DWORD start=0,end=0;SendMessageW(edit,EM_GETSEL,(WPARAM)&start,(LPARAM)&end);bool selected=start==0&&end==15;DestroyWindow(edit);if(!selected)throw std::runtime_error("Ctrl+A did not select native input text");
 auto parent=CreateWindowExW(0,L"STATIC",L"",0,0,0,200,100,nullptr,nullptr,GetModuleHandle(nullptr),nullptr);auto checkBox=CreateWindowExW(0,L"BUTTON",L"",WS_CHILD|BS_AUTOCHECKBOX,0,0,22,22,parent,nullptr,GetModuleHandle(nullptr),nullptr);SetWindowSubclass(checkBox,checkPaintProc,9,0);SendMessageW(checkBox,BM_CLICK,0,0);bool toggled=SendMessageW(checkBox,BM_GETCHECK,0,0)==BST_CHECKED;SendMessageW(checkBox,BM_CLICK,0,0);toggled&=SendMessageW(checkBox,BM_GETCHECK,0,0)==BST_UNCHECKED;DestroyWindow(checkBox);DestroyWindow(parent);if(!toggled)throw std::runtime_error("Custom checkbox lost native toggle behavior");
 atomicWrite(folder/"native-layout-result.json",json{{"ok",true},{"responsive_widths",5},{"dark_options",true},{"input_select_all",true},{"checkbox_toggle",true},{"thumbnail_capacity",thumbnailCapacity},{"gui_opened",false}}.dump(2));return 0;
 }catch(const std::exception& e){atomicWrite(folder/"native-layout-result.json",json{{"ok",false},{"error",e.what()},{"gui_opened",false}}.dump(2));return 1;}}

